namespace sv_3f82dd67d80b4fe590441c9a9ec10653.Client.Models;

public sealed class Shipment
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public required DateTimeOffset EstimatedDelivery { get; init; }
    public required IReadOnlyList<StatusUpdate> StatusUpdates { get; init; }
}

public sealed class StatusUpdate
{
    public required DateTimeOffset Timestamp { get; init; }
    public required string Description { get; init; }
    public required string Location { get; init; }
}

using sv_3f82dd67d80b4fe590441c9a9ec10653.Client.Models;

namespace sv_3f82dd67d80b4fe590441c9a9ec10653.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_3f82dd67d80b4fe590441c9a9ec10653.Client.Models;
using sv_3f82dd67d80b4fe590441c9a9ec10653.Client.Services;

namespace sv_3f82dd67d80b4fe590441c9a9ec10653.Services;

public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Memphis, TN",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 14, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 8, 9, 0, 0, TimeSpan.Zero), Description = "Package picked up", Location = "Los Angeles, CA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 9, 3, 30, 0, TimeSpan.Zero), Description = "Departed facility", Location = "Los Angeles, CA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 9, 18, 45, 0, TimeSpan.Zero), Description = "Arrived at sorting center", Location = "Memphis, TN" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 10, 6, 15, 0, TimeSpan.Zero), Description = "In transit to destination", Location = "Memphis, TN" },
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "New York, NY",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 9, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 6, 14, 0, 0, TimeSpan.Zero), Description = "Package picked up", Location = "Chicago, IL" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 7, 8, 0, 0, TimeSpan.Zero), Description = "In transit", Location = "Columbus, OH" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 8, 11, 20, 0, TimeSpan.Zero), Description = "Out for delivery", Location = "New York, NY" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 8, 14, 35, 0, TimeSpan.Zero), Description = "Delivered — signed by J. Smith", Location = "New York, NY" },
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 18, 20, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 10, 0, 5, 0, TimeSpan.Zero), Description = "Order placed, awaiting pickup", Location = "Seattle, WA" },
            ]
        }
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net.Http.Json;
using sv_3f82dd67d80b4fe590441c9a9ec10653.Client.Models;

namespace sv_3f82dd67d80b4fe590441c9a9ec10653.Client.Services;

/// <summary>
/// Used on the WebAssembly side — calls the server API over HTTP.
/// </summary>
public sealed class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var encoded = Uri.EscapeDataString(trackingNumber);
        var response = await http.GetAsync($"api/shipments/{encoded}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

